import{_ as e,o as l,c as r,a2 as i}from"./chunks/framework.CdvW4CUT.js";const b=JSON.parse('{"title":"遊玩規範","description":"本伺服的遊玩規範，請玩家們遵守。","frontmatter":{"title":"遊玩規範","description":"本伺服的遊玩規範，請玩家們遵守。"},"headers":[],"relativePath":"rule/history/20220627/index.md","filePath":"rule/history/20220627.md"}'),t={name:"rule/history/20220627/index.md"};function o(h,a,u,n,s,d){return l(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="遊玩規範-2022-06-27" tabindex="-1">遊玩規範(2022-06-27) <a class="header-anchor" href="#遊玩規範-2022-06-27" aria-label="Permalink to &quot;遊玩規範(2022-06-27)&quot;">​</a></h1><p>風平浪靜 NagiAsu.xyz，提供Minecraft多人伺服器遊玩、Discord社群、網站、資訊、服務等，供使用者遊玩與使用。<br> 當您加入伺服器遊玩後，即視為您已詳細了解並同意本規定；若您對本規定有任何疑慮，應立即向伺服方詢問。 若不願意遵守本規定，遊玩方應立即停止使用本服務。</p><ul><li>最後更新時間 : 2022/06/27</li></ul><h3 id="公共頻道發言-請遵守公共頻道聊天規範" tabindex="-1">公共頻道發言，請遵守<a href="/rule/history/rule/chat/"><b>公共頻道聊天規範</b></a> <a class="header-anchor" href="#公共頻道發言-請遵守公共頻道聊天規範" aria-label="Permalink to &quot;公共頻道發言，請遵守[&lt;b&gt;公共頻道聊天規範&lt;/b&gt;](./rule/chat.md)&quot;">​</a></h3><ul><li>此為獨立頁面超連結，請點擊上方連結查看</li></ul><h3 id="請勿影響其他玩家遊玩" tabindex="-1">請勿影響其他玩家遊玩 <a class="header-anchor" href="#請勿影響其他玩家遊玩" aria-label="Permalink to &quot;請勿影響其他玩家遊玩&quot;">​</a></h3><ul><li><strong>影響他人</strong>的行為係指： <ul><li>破壞、偷竊、騷擾、詐欺、誤導、盜畫、影響效能...</li></ul></li><li>基本上，在路上看到人造建築與箱子不要任意去亂碰</li></ul><h3 id="嚴禁使用外掛功能-遊戲bug" tabindex="-1">嚴禁使用外掛功能/遊戲BUG <a class="header-anchor" href="#嚴禁使用外掛功能-遊戲bug" aria-label="Permalink to &quot;嚴禁使用外掛功能/遊戲BUG&quot;">​</a></h3><ul><li><a href="/rule/history/rule/modrule/">容許與禁止的詳細說明</a></li></ul><h3 id="請勿開分身或使用vpn遊玩" tabindex="-1">請勿開分身或使用VPN遊玩 <a class="header-anchor" href="#請勿開分身或使用vpn遊玩" aria-label="Permalink to &quot;請勿開分身或使用VPN遊玩&quot;">​</a></h3><ul><li>若有這類需求，請務必<b>主動</b>利用<a href="/rule/history/contact/">客服</a>向伺服人員詢問或提出申請</li><li>違反本項規定將依照伺服人員之認定進行處置</li></ul><h3 id="嚴禁影響伺服運作" tabindex="-1">嚴禁影響伺服運作 <a class="header-anchor" href="#嚴禁影響伺服運作" aria-label="Permalink to &quot;嚴禁影響伺服運作&quot;">​</a></h3><h2 id="備註" tabindex="-1">備註 <a class="header-anchor" href="#備註" aria-label="Permalink to &quot;備註&quot;">​</a></h2><ul><li>伺服處理以帳號與IP為準，請務必保管好個人帳號 <ul><li>切勿外借給任何人，若發生任何狀況須自行承擔責任</li><li>帳號之所有行為皆視為您本人之行為，不接受任何因個人因素導致之理由(朋友玩的/家人玩的/帳號被盜...)作為要求重新提供服務之依據。</li></ul></li><li>若發現有玩家有違反以上規定時，請即時利用<a href="/rule/history/discord/customer_service/">客服系統</a>通報，切勿知情不報</li><li>除現有規定，若有對伺服造成負面損害之規定外行為，伺服方保有隨時停止向該玩家提供服務之權利</li></ul><p><font size="4"><a href="/rule/history/rule/punish/">解除遊玩契約與上訴</a></font></p>',15)])])}const f=e(t,[["render",o]]);export{b as __pageData,f as default};
